const inputItems = $input.all();

return inputItems.map((item, index) => {
  const data = item.json || {};
  const workflow = data.workflow || {};
  const execution = data.execution || {};
  const error = execution.error || data.error || {};

  const workflowName = workflow.name || 'Unbekannter Workflow';
  const nodeName = execution.lastNodeExecuted || 'Unbekannter Node';
  const executionId = execution.id || '-';
  const executionUrl = execution.url || '-';
  const errorMessage = error.message || JSON.stringify(error) || 'Keine Fehlermeldung vorhanden';

  return {
    json: {
      ...data,
      _alert: {
        subject: `n8n GLOBALER FEHLER: ${workflowName}`,
        message:
`Ein n8n-Workflow ist unerwartet fehlgeschlagen.

Workflow: ${workflowName}
Workflow-ID: ${workflow.id || '-'}
Fehlgeschlagener Node: ${nodeName}
Execution-ID: ${executionId}
Execution-URL: ${executionUrl}
Zeitpunkt: ${new Date().toISOString()}

Fehler:
${errorMessage}

Dieser Workflow ist der globale Notfall-Handler für ungefangene Fehler.`
      }
    },
    pairedItem: { item: index }
  };
});

