const inputItems = $input.all();
const staticData = $getWorkflowStaticData('global');

const now = new Date();
const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/Berlin',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).formatToParts(now);

const getPart = (type) => parts.find((p) => p.type === type)?.value;
const today = `${getPart('year')}-${getPart('month')}-${getPart('day')}`;

if (staticData.aiLimitDate !== today) {
  staticData.aiLimitDate = today;
  staticData.aiLimitCount = 0;
  staticData.aiLimitAlertSent = false;
}

staticData.aiLimitCount = Number(staticData.aiLimitCount || 0) + 1;

const limit = 20;
const allowed = staticData.aiLimitCount <= limit;
const notify = !allowed && !staticData.aiLimitAlertSent;

if (notify) {
  staticData.aiLimitAlertSent = true;
}

return inputItems.map((item, index) => ({
  json: {
    ...item.json,
    _rateLimit: {
      date: today,
      timezone: 'Europe/Berlin',
      count: staticData.aiLimitCount,
      limit,
      allowed,
      notify,
    },
  },
  pairedItem: { item: index },
}));

const inputItems = $input.all();

return inputItems.map((item, index) => {
  const r = item.json._rateLimit || {};
  return {
    json: {
      ...item.json,
      _alert: {
        subject: 'n8n Warnung: Tägliches KI-Limit überschritten',
        message:
`Der Recipe-gemini-Workflow hat das tägliche KI-Limit erreicht.

Datum: ${r.date || '-'}
Zeitzone: ${r.timezone || 'Europe/Berlin'}
Gezählte Aufrufe: ${r.count ?? '-'}
Limit: ${r.limit ?? '-'}

Der AI Agent wurde für diesen und weitere Aufrufe heute NICHT ausgeführt.
Diese Limit-Mail wird pro Tag nur einmal verschickt.

Fehlercode: DAILY_AI_LIMIT_EXCEEDED`
      }
    },
    pairedItem: { item: index }
  };
});

const inputItems = $input.all();

return inputItems.map((item, index) => {
  let details = '';
  try {
    details = JSON.stringify(item.json, null, 2);
  } catch {
    details = String(item.json);
  }

  return {
    json: {
      ...item.json,
      _alert: {
        subject: 'n8n Fehler: Gemini / AI Agent fehlgeschlagen',
        message:
`Im Recipe-gemini-Workflow ist der AI Agent bzw. Gemini/Structured Output fehlgeschlagen.

Zeitpunkt: ${new Date().toISOString()}

Der Webhook erhält HTTP 503 und der Supabase-Zweig wird für diesen Request nicht ausgeführt.

Fehlerdaten:
${details}`
      }
    },
    pairedItem: { item: index }
  };
});

const inputItems = $input.all();

return inputItems.map((item, index) => {
  let details = '';
  try {
    details = JSON.stringify(item.json, null, 2);
  } catch {
    details = String(item.json);
  }

  return {
    json: {
      ...item.json,
      _alert: {
        subject: 'n8n Fehler: Supabase-Speicherung fehlgeschlagen',
        message:
`Im Recipe-gemini-Workflow konnte mindestens ein Rezept nicht in Supabase gespeichert werden.

Zeitpunkt: ${new Date().toISOString()}

Hinweis:
Die erfolgreiche Webhook-Antwort wird im bestehenden Aufbau direkt nach dem AI Agent gesendet. Deshalb kann der Client das Rezept bereits erhalten haben, obwohl die Datenbank-Speicherung danach fehlgeschlagen ist.

Fehlerdaten:
${details}`
      }
    },
    pairedItem: { item: index }
  };
